import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import "../styles/UserGig.css"; // optional for styling

const UserGig = () => {
  const { gigId } = useParams();
  const navigate = useNavigate();
  const [gig, setGig] = useState(null);

  useEffect(() => {
    const fetchGig = async () => {
      try {
        const response = await axios.get(`http://localhost:5000/api/gigs/${gigId}`);
        setGig(response.data);
      } catch (error) {
        console.error("Error fetching gig:", error);
      }
    };

    fetchGig();
  }, [gigId]);

  const handleViewProfile = () => {
    if (gig?.userId) {
      navigate(`/profile/${gig.userId}`);
    } else {
      console.warn("User ID not found in gig data.");
    }
  };

  if (!gig) {
    return <div>Loading gig details...</div>;
  }

  return (
    <div className="gig-container">
      <h2 className="profile-title">GIG POSTING</h2>

      <div className="form-group">
        <label>Title</label>
        <input type="text" value={gig.title || ""} readOnly />
      </div>

      <div className="form-group">
        <label>Gig Type</label>
        <input type="text" value={gig.gigType || ""} readOnly />
      </div>

      <div className="form-group">
        <label>Genre</label>
        <input type="text" value={Array.isArray(gig.genre) ? gig.genre.join(", ") : gig.genre || ""} readOnly />
      </div>

      <div className="form-group">
        <label>City</label>
        <input type="text" value={gig.city || ""} readOnly />
      </div>

      <div className="form-group">
        <label>Description</label>
        <textarea value={gig.description || ""} readOnly />
      </div>

      <div className="form-group">
        <label>Date Posted</label>
        <input type="text" value={gig.datePosted?.split("T")[0] || ""} readOnly />
      </div>

      <div className="form-group">
        <label>Expires</label>
        <input type="text" value={gig.expiryDate?.split("T")[0] || ""} readOnly />
      </div>

      <div className="form-group">
        <label>Posted By</label>
        <input type="text" value={gig.username || ""} readOnly />
      </div>

      <button className="view-profile-button" onClick={handleViewProfile}>
        View User Profile
      </button>
    </div>
  );
};

export default UserGig;
